RKfill("css",[{"b":["CSS (Cascading Style Sheets) mengatur tampilan HTML. Satu <b>aturan</b> terdiri dari <b>selector</b> (elemen mana) dan blok <b>deklarasi</b> di dalam kurung kurawal. Setiap deklarasi adalah pasangan <code>properti: nilai;</code>.","Contoh: <code>h1 { color: #B4532A; font-size: 32px; }</code> berarti \"semua h1 berwarna terakota dan berukuran 32 piksel\". Komentar ditulis <code>/* ... */</code>.","Ubah nilai di panel CSS dan lihat hasilnya langsung."],"html":"<h1>Toko Nusantara</h1>\n<p>Kopi, teh, dan camilan pilihan.</p>\n<p class=\"promo\">Promo: gratis ongkir!</p>","css":"/* aturan untuk semua h1 */\nh1 {\n  color: #B4532A;\n  font-family: Georgia, serif;\n}\np {\n  color: #444;\n  line-height: 1.6;\n}\n.promo {\n  background: #FBE7A8;\n  padding: 6px 10px;\n}","task":{"q":"Buat semua paragraf berukuran huruf <code>18px</code>.","test":"getComputedStyle(document.querySelector('p')).fontSize==='18px'","hint":"Tambahkan font-size: 18px; di aturan p."},"pts":["Aturan = selector + { deklarasi }.","Deklarasi = properti: nilai; dan diakhiri titik koma.","Komentar CSS: /* ... */."],"q":[["Bagian mana yang menentukan elemen sasaran?",["Selector","Properti","Nilai"],0,"Selector memilih elemen."]],"so":[{"q":"Tulis aturan agar semua h2 berwarna #2E5E8C, berukuran 24px, dan bergaris bawah tipis.","h":"Satu selector, tiga deklarasi.","a":"h2 {\n  color: #2E5E8C;\n  font-size: 24px;\n  border-bottom: 1px solid #ddd;\n}","lang":"css"},{"q":"Temukan dua kesalahan: <code>p { color red; font-size: 16 }</code>","h":"Setiap deklarasi butuh titik dua; angka panjang butuh satuan.","a":"p {\n  color: red;       /* kurang titik dua */\n  font-size: 16px;  /* kurang satuan px */\n}","lang":"css"}],"deep":{"ist":[["Rule set","Selector + blok deklarasi { properti: nilai; }."],["Shorthand property","Satu properti yang mengisi beberapa sekaligus: margin, padding, font, border, inset."],["Logical properties","margin-inline, padding-block, inset-inline-start: mengikuti arah tulisan (penting untuk RTL)."],["Stylelint","Linter CSS untuk menangkap kesalahan dan menegakkan konvensi tim."]],"cx":[{"t":"Shorthand dan logical properties","code":".kartu {\n  /* longhand */\n  margin-top: 16px; margin-right: 0; margin-bottom: 16px; margin-left: 0;\n  /* shorthand setara */\n  margin: 16px 0;\n  /* logical: otomatis benar untuk bahasa kanan-ke-kiri (Arab) */\n  padding-block: 1rem;          /* atas & bawah */\n  padding-inline: 1.25rem;      /* awal & akhir baris */\n  border-inline-start: 4px solid var(--warna-aksen);\n  font: 600 1rem/1.5 \"Inter\", system-ui, sans-serif;   /* weight size/line-height family */\n}","lang":"css"}]}},{"b":["Selector elemen memilih berdasarkan nama tag (<code>p</code>), selector class memakai titik (<code>.harga</code>), selector id memakai pagar (<code>#keranjang</code>), dan <code>*</code> memilih semua elemen.","Beberapa selector bisa digabung dengan koma agar berbagi gaya: <code>h1, h2, h3 { ... }</code>. Selector juga bisa digabung tanpa spasi untuk syarat ganda: <code>p.promo</code> berarti paragraf yang punya class promo.","Kebiasaan baik: utamakan class. Hindari id untuk gaya, karena id sangat kuat dan sulit ditimpa."],"html":"<h2>Keranjang</h2>\n<p class=\"item\">Kopi Gayo <span class=\"harga\">Rp85.000</span></p>\n<p class=\"item habis\">Rendang Kaleng <span class=\"harga\">Rp75.000</span></p>\n<p id=\"total\">Total: Rp85.000</p>","css":"* { box-sizing: border-box; }\nh2, #total { font-family: Georgia, serif; }\n.item { padding: 6px; border-bottom: 1px solid #ddd; }\n.harga { float: right; font-weight: 600; }\np.habis { color: #999; text-decoration: line-through; }\n#total { font-size: 20px; }","task":{"q":"Buat semua elemen dengan class <code>harga</code> berwarna hijau <code>rgb(47, 122, 82)</code>.","test":"getComputedStyle(document.querySelector('.harga')).color==='rgb(47, 122, 82)'","hint":".harga { color: #2F7A52; }"},"pts":[".class, #id, tag, dan * adalah selector sederhana.","Koma mengelompokkan selector.","Utamakan class untuk gaya."],"q":[["Selector untuk class \"menu\"?",[".menu","#menu","menu"],0,"Titik untuk class."],["p.promo memilih?",["Paragraf yang punya class promo","Semua p dan semua .promo","Elemen promo di dalam p"],0,"Tanpa spasi berarti syarat ganda pada elemen yang sama."]],"so":[{"q":"Beri warna merah pada semua elemen ber-class <code>error</code> dan tebalkan elemen ber-id <code>total</code>.","h":".class dan #id.","a":".error { color: #C0392B; }\n#total { font-weight: 700; }","lang":"css"},{"q":"Beri gaya yang sama untuk h1, h2, dan h3 sekaligus.","h":"Pisahkan selector dengan koma.","a":"h1, h2, h3 {\n  font-family: Georgia, serif;\n  line-height: 1.2;\n}","lang":"css"}],"pro":[{"t":"Satu selector untuk beberapa keadaan dengan :is()","tag":"Lebih singkat","why":"<code>:is()</code> menggabungkan daftar selector yang berulang. <code>:focus-visible</code> menampilkan garis fokus hanya untuk pengguna keyboard, bukan saat diklik dengan mouse.","lang":"css","a":".menu a:hover, .menu a:focus, .footer a:hover, .footer a:focus {\n  text-decoration: underline;\n}","b":":is(.menu, .footer) a:is(:hover, :focus-visible) {\n  text-decoration: underline;\n}"}],"deep":{"ist":[["Type, class, id selector","p, .kartu, #utama; kelas adalah pilihan utama untuk gaya."],["Attribute selector","[type=\"email\"], [href^=\"https\"], [data-status=\"lunas\"]."],["Universal selector","* memilih semua; dipakai untuk reset box-sizing."],["Selector performance","Browser modern cepat; yang lebih penting adalah keterbacaan dan specificity rendah."]],"cx":[{"t":"Selector atribut untuk status data","code":"*, *::before, *::after { box-sizing: border-box; }\n\n.lencana { padding: .125rem .5rem; border-radius: 999px; font-size: .75rem; }\n.lencana[data-status=\"lunas\"]   { background: #e6f4ea; color: #1e6b34; }\n.lencana[data-status=\"pending\"] { background: #fff4e5; color: #8a4b00; }\n.lencana[data-status=\"gagal\"]   { background: #fdecea; color: #a1281e; }\n\na[href^=\"http\"]:not([href*=\"tokokopi.id\"])::after { content: \" ↗\"; }   /* tanda link eksternal */\na[href$=\".pdf\"]::after { content: \" (PDF)\"; }\ninput[type=\"number\"] { font-variant-numeric: tabular-nums; }","lang":"css"}]}},{"viz":"specificity","b":["Kalau dua aturan mengatur properti yang sama, siapa yang menang? Browser memeriksa berurutan: <b>pentingnya</b> (!important), lalu <b>specificity</b> (kekuatan selector), lalu <b>urutan</b> (yang ditulis belakangan menang).","Specificity dihitung sebagai tiga angka (a, b, c): a = jumlah id, b = jumlah class, atribut, dan pseudo-class, c = jumlah elemen dan pseudo-element. Bandingkan dari kiri: (1,0,0) mengalahkan (0,9,9).","Gaya inline mengalahkan semuanya kecuali !important. Hindari !important; jika butuh, biasanya selectormu terlalu rumit."],"html":"<p id=\"info\" class=\"pesan penting\">Warna apa saya?</p>","css":"p { color: gray; }               /* (0,0,1) */\n.pesan { color: green; }         /* (0,1,0) */\np.pesan.penting { color: blue; } /* (0,2,1) menang dari .pesan */\n.pesan { color: orange; }        /* (0,1,0) kalah walau ditulis belakangan */","task":{"q":"Tanpa menghapus aturan yang ada, buat paragraf berwarna merah <code>rgb(255, 0, 0)</code> dengan selector id.","test":"getComputedStyle(document.querySelector('p')).color==='rgb(255, 0, 0)'","hint":"#info { color: red; } punya specificity (1,0,0)."},"pts":["Urutan penentuan: !important, specificity, lalu urutan tulis.","Specificity (id, class, elemen) dibandingkan dari kiri.","Inline style sangat kuat; hindari !important."],"q":[["Mana yang menang: #menu a atau .nav .menu a?",["#menu a (1,0,1)",".nav .menu a (0,2,1)","Yang ditulis terakhir"],0,"Satu id mengalahkan berapa pun class."]],"so":[{"q":"Urutkan dari spesifisitas terendah ke tertinggi: <code>#menu a</code>, <code>a</code>, <code>.nav a</code>, <code>nav a:hover</code>.","h":"Hitung (id, class/pseudo-class, elemen).","a":"a              → (0,0,1)\nnav a:hover    → (0,1,2)\n.nav a         → (0,1,1)   lebih rendah dari nav a:hover\n#menu a        → (1,0,1)\n\nUrutan: a < .nav a < nav a:hover < #menu a","lang":"css"},{"q":"Tombol tetap biru walau kamu menulis <code>.btn { background: green; }</code>. Bagaimana memperbaikinya tanpa !important?","h":"Kemungkinan ada aturan lebih spesifik, misalnya #form .btn. Samakan atau naikkan spesifisitas, atau tata ulang dengan class.","a":"/* aturan lama yang menang */\n#form .btn { background: blue; }\n\n/* perbaikan: ubah aturan yang sama spesifiknya */\n#form .btn { background: green; }\n/* lebih baik lagi: hindari id di CSS, pakai class saja */","lang":"css"}],"deep":{"ist":[["Cascade","Urutan penentuan gaya: origin & !important, cascade layer, specificity, lalu urutan muncul."],["Specificity (a,b,c)","id = (1,0,0), kelas/atribut/pseudo-class = (0,1,0), elemen = (0,0,1)."],["@layer","Cascade layers: mengatur prioritas kelompok CSS (reset, framework, komponen, utilitas) tanpa perang specificity."],["!important","Pengecualian terakhir; jika sering dipakai, tanda arsitektur CSS bermasalah."]],"cx":[{"t":"Menghitung specificity seperti browser","code":"function specificity(sel) {\n  const s = sel.replace(/:not\\(([^)]*)\\)/g, \" $1 \");       // :not() dihitung dari isinya\n  const a = (s.match(/#[\\w-]+/g) || []).length;\n  const b = (s.match(/\\.[\\w-]+|\\[[^\\]]+\\]|(?<!:):(?!:)[\\w-]+/g) || []).length;\n  const c = (s.replace(/#[\\w-]+|\\.[\\w-]+|\\[[^\\]]+\\]|:{1,2}[\\w-]+/g, \" \").match(/(^|[\\s>+~])[a-z][\\w-]*/gi) || []).length\n          + (s.match(/::[\\w-]+/g) || []).length;\n  return [a, b, c];\n}\nconst daftar = [\"p\", \".tombol\", \"nav a:hover\", \"#header .menu li\", \"button.tombol.utama:not(.nonaktif)\", \"a::before\"];\nfor (const sel of daftar) console.log(sel.padEnd(38), specificity(sel).join(\",\"));\nconst menang = daftar.reduce((x, y) => (specificity(y).join() > specificity(x).join() ? y : x));\nconsole.log(\"paling kuat:\", menang);","lang":"js","out":"p                                      0,0,1\n.tombol                                0,1,0\nnav a:hover                            0,1,2\n#header .menu li                       1,1,1\nbutton.tombol.utama:not(.nonaktif)     0,3,1\na::before                              0,0,2\npaling kuat: #header .menu li"},{"t":"@layer: prioritas ditentukan urutan layer, bukan specificity","b":"Gaya di layer yang dideklarasikan belakangan selalu menang atas layer sebelumnya, berapa pun specificity-nya.","code":"@layer reset, framework, komponen, utilitas;\n\n@layer framework {\n  #app .btn.btn-primary { background: blue; }      /* specificity tinggi */\n}\n@layer komponen {\n  .tombol { background: var(--hijau); }             /* menang: layer belakangan */\n}\n@layer utilitas {\n  .sembunyi { display: none; }\n}","lang":"css"}]}},{"viz":"boxmodel","b":["Setiap elemen digambar sebagai kotak berlapis: <b>content</b> (isi), <b>padding</b> (jarak di dalam), <b>border</b> (garis tepi), dan <b>margin</b> (jarak ke elemen lain).","Secara bawaan, <code>width</code> hanya mengukur isi, jadi padding dan border menambah lebar total. Dengan <code>box-sizing: border-box</code>, width sudah termasuk padding dan border. Hampir semua proyek modern memasang <code>*{box-sizing:border-box}</code>.","Margin vertikal dua blok yang bersebelahan bisa <b>runtuh</b> (collapse) menjadi satu, diambil yang terbesar. <code>outline</code> mirip border tapi tidak memakan ruang, sering dipakai untuk penanda fokus."],"html":"<div class=\"kotak a\">content-box: lebar 200 + padding + border</div>\n<div class=\"kotak b\">border-box: lebar tepat 200</div>","css":".kotak { width: 200px; padding: 20px; border: 6px solid #2E5E8C; margin: 12px 0; background: #E9EFF5; font: 13px sans-serif; }\n.a { box-sizing: content-box; }\n.b { box-sizing: border-box; }","task":{"q":"Ubah kotak <code>.a</code> agar lebar totalnya juga tepat 200px.","test":"document.querySelector('.a').getBoundingClientRect().width===200","hint":"Ganti box-sizing .a menjadi border-box."},"pts":["Lapisan kotak: content, padding, border, margin.","border-box: width sudah termasuk padding dan border.","Margin vertikal bisa runtuh.","outline tidak memakan ruang."],"q":[["width 200px, padding 20px, border 5px, content-box. Lebar total?",["250px","200px","225px"],0,"200 + 2×20 + 2×5 = 250."],["Yang memberi jarak di dalam border?",["padding","margin","outline"],0,"Padding ada di antara isi dan border."]],"so":[{"q":"Kotak lebar 300px, padding 20px, border 5px. Berapa lebar totalnya dengan box-sizing bawaan, dan bagaimana agar tetap 300px?","h":"content-box: 300 + 2×20 + 2×5. Pakai border-box.","a":"/* content-box: 300 + 40 + 10 = 350px */\n*, *::before, *::after { box-sizing: border-box; }\n.kotak { width: 300px; padding: 20px; border: 5px solid; } /* total 300px */","lang":"css"},{"q":"Taruh kartu lebar maksimal 600px di tengah halaman dengan jarak atas-bawah 2rem.","h":"margin-inline: auto dan max-width.","a":".kartu {\n  max-width: 600px;\n  margin: 2rem auto;\n  padding: 1.5rem;\n}","lang":"css"}],"pro":[{"t":"box-sizing: border-box untuk semua elemen","tag":"Best practice","why":"Secara bawaan, padding dan border ditambahkan di luar <code>width</code>, sehingga kotak 300px dengan padding 20px menjadi 342px. Dengan <code>border-box</code>, lebar yang ditulis adalah lebar akhirnya.","lang":"css","a":".kartu {\n  width: 258px; /* 300 - 2x20 padding - 2x1 border, dihitung manual */\n  padding: 20px;\n  border: 1px solid #ccc;\n}","b":"*, *::before, *::after { box-sizing: border-box; }\n.kartu {\n  width: 300px;\n  padding: 20px;\n  border: 1px solid #ccc;\n}"}],"deep":{"ist":[["content / padding / border / margin","Empat lapisan kotak setiap elemen."],["box-sizing: border-box","Lebar sudah termasuk padding dan border; standar hampir semua proyek."],["Margin collapsing","Margin vertikal dua blok bersebelahan bergabung menjadi yang terbesar, bukan dijumlah."],["DevTools box model","Panel di Inspect Element untuk melihat ukuran tiap lapisan."]],"cx":[{"t":"Berapa lebar sebenarnya? content-box vs border-box","code":"const kotak = { width: 300, padding: 24, border: 2, margin: 16 };\nconst contentBox = kotak.width + 2 * kotak.padding + 2 * kotak.border;\nconst borderBox = kotak.width;\nconsole.log(\"content-box: lebar terlihat\", contentBox, \"px, ruang terpakai\", contentBox + 2 * kotak.margin, \"px\");\nconsole.log(\"border-box : lebar terlihat\", borderBox, \"px, isi tersisa\", borderBox - 2 * kotak.padding - 2 * kotak.border, \"px\");\nconst margin = [32, 24];\nconsole.log(\"dua margin vertikal\", margin.join(\" & \"), \"-> jarak\", Math.max(...margin), \"px (collapse), bukan\", margin[0] + margin[1]);","lang":"js","out":"content-box: lebar terlihat 352 px, ruang terpakai 384 px\nborder-box : lebar terlihat 300 px, isi tersisa 248 px\ndua margin vertikal 32 & 24 -> jarak 32 px (collapse), bukan 56"}]}},{"b":["<b>px</b> adalah unit absolut. Unit relatif menyesuaikan konteks: <code>%</code> (persen dari induk), <code>em</code> (dari ukuran huruf elemen itu), <code>rem</code> (dari ukuran huruf root, biasanya 16px), <code>vw</code>/<code>vh</code> (persen lebar/tinggi layar), dan <code>ch</code> (lebar karakter \"0\").","Pakai <b>rem</b> untuk ukuran huruf agar menghormati pengaturan ukuran huruf pengguna. Fungsi <code>calc()</code> mencampur unit (<code>calc(100% - 2rem)</code>), <code>min()</code>/<code>max()</code> memilih nilai, dan <code>clamp(min, ideal, max)</code> membuat ukuran fleksibel dengan batas."],"html":"<div class=\"wadah\">\n  <h2>Judul fleksibel</h2>\n  <p class=\"baca\">Paragraf ini dibatasi sekitar 45 karakter per baris agar nyaman dibaca, apa pun lebar layarnya.</p>\n  <div class=\"bar\"></div>\n</div>","css":"html { font-size: 16px; }\nh2 { font-size: clamp(1.25rem, 4vw, 2.5rem); }\n.baca { max-width: 45ch; font-size: 1rem; }\n.bar { width: calc(100% - 2rem); height: .5rem; background: #2F7A52; border-radius: 1em; }","pts":["rem untuk ukuran huruf, menghormati pengaturan pengguna.","% dan vw untuk lebar fleksibel.","calc() mencampur unit, clamp() membatasi ukuran fleksibel.","ch cocok untuk membatasi panjang baris."],"q":[["1.5rem bila root 16px?",["24px","16px","1.5px"],0,"1.5 × 16 = 24."],["clamp(1rem, 4vw, 2rem) berarti?",["4vw, tapi tidak kurang dari 1rem dan tidak lebih dari 2rem","Selalu 4vw","Rata-rata ketiganya"],0,"clamp menjaga nilai di antara batas bawah dan atas."]],"so":[{"q":"Buat ukuran huruf judul yang menyesuaikan lebar layar tapi tidak lebih kecil dari 1.5rem atau lebih besar dari 3rem.","h":"clamp(min, ideal, max).","a":"h1 { font-size: clamp(1.5rem, 4vw + 1rem, 3rem); }","lang":"css"},{"q":"Root font-size 16px. Berapa piksel 1.5rem, dan berapa 2em di dalam elemen yang font-size-nya 20px?","h":"rem mengacu ke root (html), em mengacu ke font-size elemen itu sendiri atau induknya.","a":"1.5rem = 1.5 × 16 = 24px\n2em (font-size induk 20px) = 2 × 20 = 40px","lang":"css"}],"deep":{"ist":[["rem / em","rem relatif ke font root (aman dan konsisten); em relatif ke font elemen induk."],["Viewport units","vw, vh, dvh (dynamic viewport, memperhitungkan bilah browser ponsel), svh, lvh."],["clamp()","clamp(min, ideal, max) untuk tipografi dan spasi yang fluid tanpa media query."],["ch","Lebar karakter \"0\"; max-width: 65ch membatasi panjang baris yang nyaman dibaca."]],"cx":[{"t":"Tipografi fluid dan tinggi layar ponsel yang benar","code":":root { font-size: 100%; }                       /* hormati pengaturan font pengguna (biasanya 16px) */\nh1 { font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem); }   /* 28px di ponsel -> 48px di desktop */\n.konten { max-width: 65ch; margin-inline: auto; padding-inline: clamp(1rem, 4vw, 3rem); }\n.hero { min-height: 100dvh; }                     /* 100vh di ponsel tertutup bilah alamat; dvh tidak */\n.ikon { inline-size: 1.25em; block-size: 1.25em; }   /* ikut besar teks di sekitarnya */\n@media (min-width: 48rem) { .grid { gap: 2rem; } }  /* breakpoint dalam rem ikut zoom pengguna */","lang":"css"},{"t":"Menghitung clamp() di beberapa lebar layar","code":"const clamp = (min, ideal, max) => Math.min(Math.max(min, ideal), max);\nfor (const vw of [360, 768, 1280, 1920]) {\n  const px = clamp(28, 1.2 * 16 + 0.025 * vw, 48);\n  console.log(`${String(vw).padStart(4)}px layar -> h1 ${px.toFixed(1)}px`);\n}","lang":"js","out":" 360px layar -> h1 28.2px\n 768px layar -> h1 38.4px\n1280px layar -> h1 48.0px\n1920px layar -> h1 48.0px"}]}},{"b":["Warna bisa ditulis dengan nama (<code>tomato</code>), hex (<code>#B4532A</code>), <code>rgb(180 83 42)</code>, atau <code>hsl(18 62% 44%)</code>. HSL paling mudah diatur manusia: hue (0–360 derajat roda warna), saturation, lightness. Tambahkan alpha untuk transparansi: <code>rgb(0 0 0 / 50%)</code>.","Properti <code>background</code> bisa berisi warna, gambar, atau gradien seperti <code>linear-gradient(135deg, #B4532A, #2E5E8C)</code>. <code>box-shadow</code> memberi bayangan dan <code>opacity</code> membuat seluruh elemen transparan.","Pastikan kontras teks dengan latar cukup: minimal 4.5:1 untuk teks biasa."],"html":"<div class=\"kartu\">\n  <h3>Promo Oktober</h3>\n  <p>Diskon 20% semua kopi.</p>\n</div>\n<div class=\"label\">hsl(18 62% 44%)</div>","css":".kartu {\n  background: linear-gradient(135deg, hsl(18 62% 44%), hsl(208 50% 36%));\n  color: white;\n  padding: 16px 20px;\n  border-radius: 14px;\n  box-shadow: 0 10px 24px rgb(0 0 0 / 25%);\n  font-family: sans-serif;\n}\n.label { margin-top: 12px; display: inline-block; padding: 4px 10px; border-radius: 99px; background: hsl(18 62% 44% / 15%); color: hsl(18 62% 34%); font: 12px monospace; }","task":{"q":"Ubah sudut gradien kartu menjadi <code>90deg</code>.","test":"getComputedStyle(document.querySelector('.kartu')).backgroundImage.includes('90deg')","hint":"linear-gradient(90deg, ...)"},"pts":["Hex, rgb, dan hsl menulis warna yang sama dengan cara berbeda.","HSL mudah diubah: geser lightness untuk versi terang/gelap.","Gradien ditulis di background-image.","Kontras teks minimal 4.5:1."],"q":[["Pada hsl(), angka pertama menyatakan?",["Hue (sudut warna)","Kecerahan","Transparansi"],0,"Hue 0–360 derajat pada roda warna."]],"so":[{"q":"Buat latar hero dengan gradasi dari terakota ke krem dan gambar yang menutupi seluruh area.","h":"Beberapa latar dipisahkan koma; background-size: cover.","a":".hero {\n  background:\n    linear-gradient(135deg, rgb(180 83 42 / .85), rgb(251 243 228 / .6)),\n    url(hero.jpg) center / cover no-repeat;\n  min-height: 60vh;\n}","lang":"css"},{"q":"Tulis warna #B4532A dalam rgb() dan buat versi transparan 20%.","h":"#B4 = 180, #53 = 83, #2A = 42.","a":"color: rgb(180 83 42);\nbackground: rgb(180 83 42 / 0.2);","lang":"css"}],"deep":{"ist":[["Contrast ratio","WCAG AA: teks normal minimal 4,5:1, teks besar dan komponen UI minimal 3:1."],["Relative luminance","Kecerahan warna yang dihitung dari nilai RGB linear; dasar rumus kontras."],["background shorthand","Gambar, posisi, ukuran, repeat, dan warna dalam satu deklarasi; bisa berlapis."],["Gradient","linear-gradient, radial-gradient, conic-gradient sebagai gambar latar."]],"cx":[{"t":"Menghitung rasio kontras WCAG untuk palet merek","b":"Hijau cerah populer untuk tombol, tetapi teks putih di atasnya sering gagal AA. Menggelapkan satu tingkat biasanya cukup.","code":"const lum = (hex) => {\n  const [r, g, b] = hex.match(/\\w\\w/g).map((x) => parseInt(x, 16) / 255)\n    .map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));\n  return 0.2126 * r + 0.7152 * g + 0.0722 * b;\n};\nconst kontras = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };\nconst pasang = [[\"#ffffff\", \"#16a34a\", \"teks putih di tombol hijau\"], [\"#ffffff\", \"#15803d\", \"putih di hijau lebih gelap\"],\n                [\"#6b7280\", \"#ffffff\", \"abu-abu di putih\"], [\"#111827\", \"#fbbf24\", \"hitam di kuning\"]];\nfor (const [fg, bg, ket] of pasang) {\n  const r = kontras(fg, bg);\n  console.log(`${ket.padEnd(28)} ${r.toFixed(2)}:1  ${r >= 4.5 ? \"lulus AA\" : r >= 3 ? \"hanya teks besar\" : \"GAGAL\"}`);\n}","lang":"js","out":"teks putih di tombol hijau   3.30:1  hanya teks besar\nputih di hijau lebih gelap   5.02:1  lulus AA\nabu-abu di putih             4.83:1  lulus AA\nhitam di kuning              10.63:1  lulus AA"}]}},{"b":["<code>font-family</code> berisi daftar huruf cadangan: <code>font-family: \"Inter\", system-ui, sans-serif</code>. Jika Inter gagal dimuat, browser memakai berikutnya. Google Fonts menyediakan ratusan huruf gratis lewat tag link.","Untuk keterbacaan: ukuran dasar 16px atau lebih, <code>line-height</code> 1.5–1.7 untuk paragraf, dan panjang baris 45–75 karakter. Tebal diatur <code>font-weight</code> (400 normal, 600 semi tebal, 700 tebal).","Properti teks lain: <code>text-align</code>, <code>text-decoration</code>, <code>text-transform: uppercase</code>, <code>letter-spacing</code>, dan <code>text-shadow</code>."],"html":"<p class=\"eyebrow\">Cerita kopi</p>\n<h1>Dari kebun Gayo ke cangkirmu</h1>\n<p class=\"isi\">Kopi Gayo tumbuh di ketinggian 1.200 meter di Aceh Tengah. Petani memetik buah merah satu per satu, lalu mengolahnya dengan proses giling basah yang membuat rasanya bersih dan seimbang.</p>","css":"body { font-family: system-ui, sans-serif; color: #1C1B19; }\n.eyebrow { text-transform: uppercase; letter-spacing: .12em; font-size: .75rem; font-weight: 600; color: #6E6B64; }\nh1 { font: 400 2rem/1.1 Georgia, serif; margin: .2em 0 .5em; }\n.isi { font-size: 1rem; line-height: 1.7; max-width: 60ch; }","task":{"q":"Ubah line-height paragraf <code>.isi</code> menjadi <code>2</code>.","test":"parseFloat(getComputedStyle(document.querySelector('.isi')).lineHeight)/parseFloat(getComputedStyle(document.querySelector('.isi')).fontSize)===2","hint":".isi { line-height: 2; }"},"pts":["Selalu tulis font cadangan di font-family.","Paragraf nyaman: 16px+, line-height 1.5–1.7, 45–75 karakter.","Shorthand font: gaya tebal ukuran/line-height keluarga."],"q":[["Line-height paragraf yang nyaman?",["1.5–1.7","0.8","3"],0,"Ruang antarbaris membantu mata pindah baris."]],"so":[{"q":"Atur teks artikel agar nyaman dibaca: lebar baris sekitar 65 karakter, jarak baris 1.6, ukuran 1.125rem.","h":"max-width dalam satuan ch.","a":"article {\n  max-width: 65ch;\n  font-size: 1.125rem;\n  line-height: 1.6;\n  font-family: \"Inter\", system-ui, sans-serif;\n}","lang":"css"},{"q":"Potong judul panjang menjadi satu baris berelipsis.","h":"white-space: nowrap, overflow: hidden, text-overflow: ellipsis.","a":".judul {\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}","lang":"css"}],"deep":{"ist":[["Type scale","Skala ukuran font dengan rasio tetap (misalnya 1,25) agar hierarki konsisten."],["line-height","1,4-1,6 untuk paragraf; judul besar lebih rapat (1,1-1,2)."],["Variable font","Satu berkas font dengan banyak ketebalan; hemat unduhan."],["font-display: swap","Teks tampil dengan font cadangan sambil menunggu font web, menghindari teks tak terlihat."]],"cx":[{"t":"Sistem tipografi dengan font variabel","code":"@font-face {\n  font-family: \"Inter\";\n  src: url(\"/fonts/inter-var.woff2\") format(\"woff2-variations\");\n  font-weight: 100 900;\n  font-display: swap;\n}\n:root {\n  --font-sans: \"Inter\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --step-0: 1rem; --step-1: 1.25rem; --step-2: 1.563rem; --step-3: 1.953rem; --step-4: 2.441rem;  /* rasio 1,25 */\n}\nbody { font-family: var(--font-sans); font-size: var(--step-0); line-height: 1.6; text-wrap: pretty; }\nh1, h2, h3 { line-height: 1.15; text-wrap: balance; letter-spacing: -0.01em; }\nh1 { font-size: var(--step-4); font-weight: 750; }\n.harga { font-variant-numeric: tabular-nums; }    /* angka sama lebar agar kolom rata */","lang":"css"}]}},{"lang":"css","b":["Selain heksa dan <code>rgb()</code>, CSS modern punya <b><code>oklch()</code></b>: <i>lightness</i>, <i>chroma</i> (kepekatan), dan <i>hue</i>. Keunggulannya, perubahan lightness terasa merata di mata manusia, sehingga membuat skala warna 100 sampai 900 jauh lebih mudah.","<b><code>color-mix()</code></b> mencampur dua warna langsung di CSS, misalnya membuat latar lembut dari warna brand tanpa menambah token baru. <b><code>light-dark()</code></b> memilih nilai untuk tema terang atau gelap sesuai <code>color-scheme</code>.","Ketiganya didukung browser modern sejak 2023 sampai 2024. Untuk browser lama, tulis nilai cadangan heksa di baris sebelumnya; browser akan memakai baris terakhir yang dipahaminya."],"pts":["oklch: lightness, chroma, hue; skala warna lebih merata.","color-mix() mencampur warna di CSS.","light-dark() memilih nilai sesuai tema.","Beri nilai cadangan untuk browser lama."],"q":[["Apa kelebihan oklch untuk membuat skala warna?",["Perubahan lightness terasa merata di mata","Ukuran file lebih kecil","Hanya bisa warna abu-abu"],0,"oklch dirancang mengikuti persepsi manusia."],["light-dark(#000, #fff) bekerja berdasarkan?",["color-scheme yang aktif","Lebar layar","Jam di perangkat"],0,"Nilai dipilih sesuai skema warna terang atau gelap."]],"code":":root {\n  color-scheme: light dark;\n  --brand: oklch(55% 0.15 255);                  /* biru */\n  --brand-soft: color-mix(in oklch, var(--brand) 15%, white);\n  --teks: light-dark(#152033, #E4EAF2);\n  --latar: light-dark(#F2F4F8, #0C121B);\n}\n\n.tombol {\n  background: #255DA2;          /* cadangan untuk browser lama */\n  background: var(--brand);\n}\n.tombol:hover { background: oklch(from var(--brand) calc(l - 0.08) c h); }\n.badge { background: var(--brand-soft); color: var(--brand); }","run":false,"deep":{"ist":[["OKLCH","Ruang warna perseptual (Lightness, Chroma, Hue); mengubah L memberi perubahan terang yang terasa seragam."],["color-mix()","Mencampur dua warna di ruang warna tertentu, misalnya untuk hover atau transparansi."],["light-dark()","Memilih warna sesuai color-scheme terang atau gelap dalam satu deklarasi."],["Wide gamut (P3)","Layar modern bisa menampilkan warna lebih jenuh daripada sRGB; OKLCH bisa menjangkaunya."]],"cx":[{"t":"Palet merek dari satu hue dengan oklch","b":"Mengganti --hue saja sudah menghasilkan palet merek baru dengan tingkat terang yang sama.","code":":root {\n  color-scheme: light dark;\n  --hue: 150;                                         /* hijau merek */\n  --hijau-50:  oklch(97% 0.03 var(--hue));\n  --hijau-500: oklch(62% 0.17 var(--hue));\n  --hijau-700: oklch(48% 0.14 var(--hue));\n  --permukaan: light-dark(#ffffff, oklch(20% 0.01 var(--hue)));\n  --teks:      light-dark(oklch(22% 0.02 var(--hue)), oklch(95% 0.01 var(--hue)));\n}\n.tombol { background: var(--hijau-700); color: white; }\n.tombol:hover { background: color-mix(in oklch, var(--hijau-700), black 12%); }\n.sorot { background: color-mix(in srgb, var(--hijau-500) 15%, transparent); }","lang":"css"}]}},{"b":["Dalam <b>alur normal</b>, elemen <b>block</b> (div, p, h1) mengambil satu baris penuh dan tersusun ke bawah, sedangkan elemen <b>inline</b> (span, a, strong) mengalir di dalam baris seperti kata. Elemen inline tidak bisa diberi width/height.","<code>inline-block</code> mengalir seperti inline tapi bisa diberi ukuran. <code>display: none</code> menghapus elemen dari tata letak, sedangkan <code>visibility: hidden</code> menyembunyikan tapi tetap memakan ruang.","<code>float</code> dulu dipakai untuk tata letak, kini hanya untuk membuat teks mengalir di sekitar gambar. Untuk tata letak, pakai flexbox atau grid."],"html":"<div class=\"blok\">blok 1</div><div class=\"blok\">blok 2</div>\n<p>Teks dengan <span class=\"in\">inline</span> dan <span class=\"ib\">inline-block</span> di dalam baris.</p>\n<p>Kotak <span class=\"hilang\">A</span> display none, kotak <span class=\"sembunyi\">B</span> visibility hidden.</p>","css":".blok{background:#E9EFF5;margin:4px 0;padding:4px}\n.in{background:#FBE7A8;width:200px}\n.ib{display:inline-block;width:120px;background:#E7F2EB;text-align:center}\n.hilang{display:none}.sembunyi{visibility:hidden;background:#ccc}","pts":["block satu baris penuh, inline mengalir dalam baris.","inline-block: dalam baris tapi bisa diberi ukuran.","display:none menghapus, visibility:hidden menyisakan ruang."],"q":[["Elemen yang tetap memakan ruang walau tak terlihat?",["visibility: hidden","display: none","opacity tidak berpengaruh"],0,"Ruangnya tetap ada."]],"so":[{"q":"Buat tautan menu tampil sejajar dan bisa diberi padding atas-bawah.","h":"inline tidak menghormati padding vertikal sepenuhnya; pakai inline-block.","a":"nav a {\n  display: inline-block;\n  padding: 0.5rem 1rem;\n}","lang":"css"},{"q":"Apa beda display: none dan visibility: hidden?","h":"none menghapus dari tata letak, hidden tetap memakan ruang.","a":".a { display: none; }       /* hilang, ruangnya ikut hilang */\n.b { visibility: hidden; }  /* tak terlihat, ruangnya tetap ada */","lang":"css"}],"deep":{"ist":[["Normal flow","Tata letak bawaan: blok bertumpuk vertikal, inline mengalir dalam baris."],["block / inline / inline-block","Menentukan apakah elemen mengambil satu baris penuh, mengalir di teks, atau keduanya."],["display: none vs visibility: hidden","none menghapus dari layout dan aksesibilitas; hidden menyisakan ruang."],["Visually hidden","Pola .sr-only menyembunyikan teks dari mata tetapi tetap dibaca pembaca layar."]],"cx":[{"t":"Menyembunyikan dengan benar sesuai tujuan","code":"/* tidak terlihat dan tidak dibaca pembaca layar */\n[hidden] { display: none !important; }\n\n/* tidak terlihat tetapi tetap dibaca pembaca layar (label tombol ikon, \"membuka tab baru\") */\n.sr-only {\n  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;\n  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;\n}\n/* skip link: tersembunyi sampai difokus keyboard */\n.skip-link { position: absolute; inset-inline-start: 1rem; translate: 0 -200%; }\n.skip-link:focus { translate: 0 1rem; }\n\n/* display: contents membuat pembungkus \"hilang\" dari layout tetapi anaknya tetap ikut grid */\n.grup-kartu { display: contents; }","lang":"css"}]}},{"b":["<code>position</code> menentukan cara elemen ditempatkan. <b>static</b> (bawaan) mengikuti alur. <b>relative</b> bergeser dari posisi aslinya dan menjadi patokan bagi anak absolute. <b>absolute</b> keluar dari alur dan diposisikan terhadap leluhur terdekat yang non-static.","<b>fixed</b> menempel pada layar (misalnya tombol chat), <b>sticky</b> mengikuti alur lalu menempel saat digulir (misalnya header tabel).","<code>z-index</code> mengatur elemen mana di atas, tapi hanya berlaku di dalam <b>stacking context</b> yang sama. Elemen dengan opacity kurang dari 1, transform, atau position + z-index membuat stacking context baru."],"html":"<div class=\"kartu\">\n  <span class=\"badge\">BARU</span>\n  <h3>Madu Hutan</h3>\n  <p>Gulir panel ini untuk melihat sticky.</p>\n  <div class=\"gulir\"><div class=\"judul\">Ulasan</div><p>Enak!</p><p>Kental.</p><p>Asli.</p><p>Mantap.</p></div>\n</div>","css":".kartu{position:relative;border:1px solid #ddd;border-radius:12px;padding:12px;font:14px sans-serif;width:260px}\n.badge{position:absolute;top:-10px;right:12px;background:#B23A2E;color:#fff;font-size:11px;padding:2px 8px;border-radius:99px}\n.gulir{height:90px;overflow:auto;border:1px solid #eee}\n.judul{position:sticky;top:0;background:#F2F1EC;font-weight:600;padding:2px 6px}","task":{"q":"Pindahkan badge ke pojok kiri atas kartu (gunakan <code>left</code>).","test":"(()=>{const b=document.querySelector('.badge').getBoundingClientRect(),k=document.querySelector('.kartu').getBoundingClientRect();return b.left-k.left<40})()","hint":"Ganti right:12px menjadi left:12px."},"pts":["relative menjadi patokan anak absolute.","absolute keluar dari alur normal.","fixed menempel di layar, sticky menempel saat digulir.","z-index hanya bersaing di stacking context yang sama."],"q":[["Absolute diposisikan terhadap?",["Leluhur terdekat yang non-static","Selalu body","Elemen sebelumnya"],0,"Biasanya induk diberi position: relative."]],"so":[{"q":"Buat tombol \"kembali ke atas\" yang selalu di pojok kanan bawah layar.","h":"position: fixed dengan right dan bottom.","a":".ke-atas {\n  position: fixed;\n  right: 1rem;\n  bottom: 1rem;\n  z-index: 50;\n}","lang":"css"},{"q":"Buat header yang menempel di atas saat halaman digulir.","h":"position: sticky; top: 0, plus latar agar konten tidak terlihat di belakangnya.","a":"header {\n  position: sticky;\n  top: 0;\n  background: white;\n  z-index: 10;\n}","lang":"css"}],"deep":{"ist":[["relative / absolute / fixed / sticky","Cara memosisikan elemen relatif terhadap dirinya, induk berposisi, viewport, atau saat menggulir."],["Containing block","Elemen acuan untuk position: absolute; induk terdekat yang punya position selain static."],["Stacking context","Kelompok lapisan; z-index hanya bersaing di dalam stacking context yang sama."],["z-index scale","Skala token (dropdown 100, sticky 200, modal 1000, toast 1100) agar tidak ada z-index: 99999."]],"cx":[{"t":"Header sticky, lencana absolut, dan skala z-index","code":":root { --z-dropdown: 100; --z-sticky: 200; --z-overlay: 900; --z-modal: 1000; --z-toast: 1100; }\n\n.header { position: sticky; top: 0; z-index: var(--z-sticky); background: var(--permukaan); }\n.ikon-keranjang { position: relative; }\n.ikon-keranjang .jumlah {\n  position: absolute; inset-block-start: -6px; inset-inline-end: -8px;\n  min-width: 1.25rem; padding-inline: .25rem; border-radius: 999px;\n}\n/* jebakan: transform/opacity < 1/filter membuat stacking context baru,\n   sehingga z-index anak tidak bisa \"keluar\" melewati elemen lain di luar induknya */\n.kartu:hover { transform: translateY(-2px); }","lang":"css"}]}},{"viz":"flexbox","b":["Flexbox menata elemen dalam <b>satu arah</b>: baris atau kolom. Pasang <code>display: flex</code> pada induk; anak-anaknya menjadi flex item.","<code>justify-content</code> mengatur posisi di sumbu utama (start, center, space-between), <code>align-items</code> di sumbu silang, <code>gap</code> memberi jarak, dan <code>flex-wrap: wrap</code> mengizinkan pindah baris.","Pada item, <code>flex: 1</code> berarti \"ambil sisa ruang\". Mainkan pengatur di visual, lalu coba di editor."],"html":"<nav class=\"bar\">\n  <strong>Toko Nusantara</strong>\n  <div class=\"menu\"><a href=\"#\">Produk</a><a href=\"#\">Promo</a><a href=\"#\">Kontak</a></div>\n  <button>Keranjang (2)</button>\n</nav>","css":".bar { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 10px 14px; background: #F2F1EC; border-radius: 12px; font: 14px sans-serif; flex-wrap: wrap; }\n.menu { display: flex; gap: 12px; }\n.menu a { color: #1C1B19; }","task":{"q":"Buat menu link tersusun vertikal (kolom).","test":"getComputedStyle(document.querySelector('.menu')).flexDirection==='column'","hint":".menu { flex-direction: column; }"},"pts":["display:flex pada induk.","justify-content = sumbu utama, align-items = sumbu silang.","gap untuk jarak, flex-wrap untuk pindah baris.","flex:1 mengambil sisa ruang."],"q":[["Menaruh item tepat di tengah horizontal dan vertikal?",["justify-content:center; align-items:center","text-align:center saja","margin:auto pada induk"],0,"Keduanya untuk dua sumbu."]],"so":[{"q":"Buat navbar: logo di kiri, menu di kanan, semuanya sejajar vertikal.","h":"display: flex; justify-content: space-between; align-items: center.","a":".navbar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 1rem;\n}","lang":"css"},{"q":"Buat deretan kartu yang turun ke baris berikutnya saat sempit, setiap kartu minimal 200px.","h":"flex-wrap: wrap dan flex: 1 1 200px.","a":".deret {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n}\n.deret > .kartu {\n  flex: 1 1 200px;\n}","lang":"css"},{"q":"Taruh satu elemen tepat di tengah layar.","h":"Wadah flex dengan justify-content dan align-items center, tinggi 100vh.","a":"body {\n  min-height: 100vh;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}","lang":"css"}],"deep":{"ist":[["Main axis / cross axis","Sumbu utama (flex-direction) dan sumbu silang; justify-content vs align-items."],["flex: 1 1 0","grow, shrink, basis; flex: 1 membagi ruang rata."],["gap","Jarak antaritem tanpa margin; didukung semua browser modern."],["min-width: 0","Item flex tidak menyusut di bawah isi terpanjangnya kecuali diberi min-width: 0; sumber overflow teks panjang."]],"cx":[{"t":"Pola flexbox sehari-hari","code":"/* navbar: logo kiri, menu kanan */\n.nav { display: flex; align-items: center; gap: 1rem; }\n.nav .spasi { margin-inline-start: auto; }\n\n/* baris item keranjang: teks panjang tidak mendorong harga keluar layar */\n.item { display: flex; gap: .75rem; align-items: center; }\n.item__nama { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.item__harga { flex-shrink: 0; font-variant-numeric: tabular-nums; }\n\n/* tag yang turun baris otomatis */\n.tag-list { display: flex; flex-wrap: wrap; gap: .5rem; }\n\n/* footer kartu selalu di bawah walau isi kartu beda tinggi */\n.kartu { display: flex; flex-direction: column; }\n.kartu__aksi { margin-block-start: auto; }","lang":"css"}]}},{"viz":"grid","b":["Grid menata dalam <b>dua arah</b> sekaligus: baris dan kolom. <code>grid-template-columns: repeat(3, 1fr)</code> membuat tiga kolom sama lebar; <code>fr</code> berarti bagian dari sisa ruang.","Pola paling berguna untuk kartu produk: <code>repeat(auto-fill, minmax(160px, 1fr))</code>. Kolom otomatis bertambah atau berkurang sesuai lebar layar, tanpa media query.","Item bisa membentang dengan <code>grid-column: span 2</code>, atau ditempatkan dengan nama area lewat <code>grid-template-areas</code>."],"html":"<div class=\"galeri\">\n  <div class=\"besar\">Kopi Gayo</div><div>Teh Melati</div><div>Keripik</div>\n  <div>Mete</div><div>Sambal</div><div>Madu</div>\n</div>","css":".galeri { display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); gap: 10px; font: 13px sans-serif; }\n.galeri div { background: #E9EFF5; border-radius: 10px; padding: 18px 10px; text-align: center; }\n.galeri .besar { grid-column: span 2; background: #F6ECE5; }","task":{"q":"Buat kotak \"Kopi Gayo\" juga membentang 2 baris.","test":"getComputedStyle(document.querySelector('.besar')).gridRowEnd.includes('span 2')","hint":".besar { grid-row: span 2; }"},"pts":["Grid untuk dua arah, flexbox untuk satu arah.","fr = bagian dari sisa ruang.","repeat(auto-fill, minmax(…, 1fr)) membuat galeri responsif.","span membentangkan item."],"q":[["Unit grid untuk \"bagian dari sisa ruang\"?",["fr","%","px"],0,"fr = fraction."]],"so":[{"q":"Buat galeri yang kolomnya otomatis menyesuaikan lebar layar, setiap kolom minimal 180px.","h":"repeat(auto-fill, minmax(180px, 1fr)).","a":".galeri {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));\n  gap: 1rem;\n}","lang":"css"},{"q":"Buat tata letak halaman dengan grid-template-areas: header, sidebar + konten, footer.","h":"Beri setiap elemen grid-area, lalu gambar petanya.","a":".halaman {\n  display: grid;\n  grid-template-columns: 220px 1fr;\n  grid-template-areas:\n    \"kepala kepala\"\n    \"samping isi\"\n    \"kaki kaki\";\n  gap: 1rem;\n}\nheader { grid-area: kepala; }\naside  { grid-area: samping; }\nmain   { grid-area: isi; }\nfooter { grid-area: kaki; }","lang":"css"}],"pro":[{"t":"Menengahkan isi dalam dua baris","tag":"Trik jarang diketahui","why":"Trik lama memakai <code>position</code> dan <code>transform</code>. Grid dengan <code>place-items: center</code> menengahkan isi secara horizontal dan vertikal.","lang":"css","a":".wadah { position: relative; height: 300px; }\n.isi {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n}","b":".wadah {\n  display: grid;\n  place-items: center;\n  height: 300px;\n}"}],"deep":{"ist":[["Grid template","grid-template-columns/rows dan areas untuk tata letak dua dimensi."],["fr unit","Bagian dari ruang sisa; 1fr 2fr membagi 1:2."],["auto-fill / auto-fit + minmax()","Kolom responsif tanpa media query: repeat(auto-fill, minmax(220px, 1fr))."],["Subgrid","Anak grid memakai garis kolom/baris induk agar isi kartu sejajar antar kartu."]],"cx":[{"t":"Katalog responsif tanpa media query dan layout halaman dengan area","code":".katalog { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(220px, 100%), 1fr)); gap: 1.5rem; }\n\n/* subgrid: judul, harga, dan tombol sejajar di semua kartu */\n.kartu { display: grid; grid-row: span 3; grid-template-rows: subgrid; gap: .5rem; }\n\n.halaman {\n  display: grid; min-height: 100dvh;\n  grid-template: \"header\" auto \"utama\" 1fr \"footer\" auto / 1fr;\n}\n@media (min-width: 64rem) {\n  .halaman { grid-template: \"header header\" auto \"sisi utama\" 1fr \"footer footer\" auto / 260px 1fr; }\n}\n.halaman > header { grid-area: header; } .halaman > aside { grid-area: sisi; }\n.halaman > main { grid-area: utama; }   .halaman > footer { grid-area: footer; }","lang":"css"},{"t":"Berapa kolom yang muncul dengan auto-fill minmax(220px, 1fr)?","code":"const kolom = (lebar, min = 220, gap = 24) => Math.max(1, Math.floor((lebar + gap) / (min + gap)));\nfor (const w of [328, 720, 1024, 1232]) {\n  const n = kolom(w); const lebarKolom = (w - (n - 1) * 24) / n;\n  console.log(`kontainer ${w}px -> ${n} kolom @ ${lebarKolom.toFixed(0)}px`);\n}","lang":"js","out":"kontainer 328px -> 1 kolom @ 328px\nkontainer 720px -> 3 kolom @ 224px\nkontainer 1024px -> 4 kolom @ 238px\nkontainer 1232px -> 5 kolom @ 227px"}]}},{"b":["Mayoritas pengguna internet Indonesia membuka situs dari ponsel. Pendekatan <b>mobile-first</b>: tulis gaya untuk layar kecil dulu, lalu tambahkan <code>@media (min-width: 640px) { ... }</code> untuk layar yang lebih lebar.","Media query juga bisa memeriksa preferensi pengguna: <code>prefers-color-scheme: dark</code> untuk mode gelap dan <code>prefers-reduced-motion</code> untuk mengurangi animasi.","Ubah lebar pratinjau dengan tombol di atasnya untuk melihat tata letak berubah."],"html":"<div class=\"tata\"><aside>Filter</aside><main>Daftar produk</main></div>","css":".tata { display: grid; gap: 10px; font: 14px sans-serif; }\n.tata > * { background: #E9EFF5; padding: 14px; border-radius: 10px; }\n/* layar lebar: dua kolom */\n@media (min-width: 480px) {\n  .tata { grid-template-columns: 140px 1fr; }\n}\n@media (prefers-color-scheme: dark) {\n  .tata > * { background: #1A2330; color: #ECEAE4; }\n}","pts":["Mobile-first: gaya dasar untuk ponsel, min-width untuk layar lebar.","Media query bisa memeriksa tema gelap dan preferensi animasi.","Selalu pasang meta viewport di HTML."],"q":[["Mobile-first memakai media query?",["min-width","max-width","orientation saja"],0,"Gaya bertambah saat layar melebar."]],"so":[{"q":"Tulis CSS mobile-first: satu kolom di ponsel, dua kolom mulai 768px, tiga kolom mulai 1024px.","h":"Gaya dasar untuk ponsel, lalu min-width.","a":".daftar { display: grid; gap: 1rem; grid-template-columns: 1fr; }\n@media (min-width: 768px) {\n  .daftar { grid-template-columns: repeat(2, 1fr); }\n}\n@media (min-width: 1024px) {\n  .daftar { grid-template-columns: repeat(3, 1fr); }\n}","lang":"css"},{"q":"Matikan animasi untuk pengguna yang memilih mengurangi gerakan, dan sesuaikan warna untuk mode gelap.","h":"prefers-reduced-motion dan prefers-color-scheme.","a":"@media (prefers-reduced-motion: reduce) {\n  * { animation: none !important; transition: none !important; }\n}\n@media (prefers-color-scheme: dark) {\n  :root { --bg: #14161A; --fg: #ECE7DF; }\n}","lang":"css"}],"pro":[{"t":"Ukuran huruf yang ikut lebar layar dengan clamp()","tag":"Trik jarang diketahui","why":"<code>clamp(min, ideal, maks)</code> membuat judul membesar mulus mengikuti lebar layar dan tidak pernah lebih kecil atau lebih besar dari batasnya. Tidak perlu tiga media query.","lang":"css","a":"h1 { font-size: 24px; }\n@media (min-width: 600px) { h1 { font-size: 32px; } }\n@media (min-width: 1000px) { h1 { font-size: 44px; } }","b":"h1 { font-size: clamp(1.5rem, 1rem + 2.5vw, 2.75rem); }"}],"deep":{"ist":[["Mobile-first","Gaya dasar untuk layar kecil, lalu tambah dengan min-width; CSS lebih sederhana dan ringan di ponsel."],["Breakpoint","Titik lebar tempat tata letak berubah; tentukan dari konten, bukan model perangkat."],["Media features","prefers-color-scheme, prefers-reduced-motion, hover, pointer: coarse."],["Range syntax","@media (48rem <= width < 64rem) lebih mudah dibaca daripada min/max."]],"cx":[{"t":"Mobile-first plus preferensi pengguna","code":".produk { display: grid; gap: 1rem; }                       /* 1 kolom: ponsel */\n@media (width >= 40rem) { .produk { grid-template-columns: 1fr 1fr; } }\n@media (width >= 64rem) { .produk { grid-template-columns: 2fr 1fr; } }\n\n@media (hover: hover) { .kartu:hover { box-shadow: var(--bayangan-2); } }   /* hover hanya untuk mouse */\n@media (pointer: coarse) { .tombol { min-block-size: 48px; } }             /* target sentuh besar */\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }\n}\n@media print { nav, .tombol { display: none; } a::after { content: \" (\" attr(href) \")\"; } }","lang":"css"}]}},{"b":["Media query melihat lebar <b>layar</b>. Container query melihat lebar <b>wadah</b> komponen, sehingga kartu yang sama bisa tampil berbeda di sidebar sempit dan di area utama yang lebar.","Tandai wadah dengan <code>container-type: inline-size</code>, lalu tulis <code>@container (min-width: 300px) { ... }</code>. Gambar responsif cukup diberi <code>max-width: 100%</code> dan <code>height: auto</code>; <code>object-fit: cover</code> memotong gambar agar pas tanpa gepeng."],"html":"<div class=\"sempit wadah\"><div class=\"kartu\"><div class=\"img\"></div><p>Kopi Gayo<br><b>Rp85.000</b></p></div></div>\n<div class=\"lebar wadah\"><div class=\"kartu\"><div class=\"img\"></div><p>Kopi Gayo<br><b>Rp85.000</b></p></div></div>","css":".wadah { container-type: inline-size; margin-bottom: 10px; font: 13px sans-serif; }\n.sempit { width: 180px; } .lebar { width: 100%; max-width: 420px; }\n.kartu { display: grid; gap: 8px; border: 1px solid #ddd; border-radius: 10px; padding: 8px; }\n.img { background: linear-gradient(135deg,#B4532A,#2E5E8C); aspect-ratio: 16/9; border-radius: 6px; }\n@container (min-width: 300px) {\n  .kartu { grid-template-columns: 120px 1fr; align-items: center; }\n}","pts":["Container query melihat lebar wadah, bukan layar.","container-type: inline-size menandai wadah.","max-width:100% dan object-fit menjaga gambar tetap rapi."],"q":[["Kapan container query lebih cocok dari media query?",["Komponen dipakai di wadah berbeda lebar","Untuk mode gelap","Untuk mencetak"],0,"Komponen menyesuaikan tempatnya."]],"so":[{"q":"Buat kartu produk yang tampil berdampingan (gambar kiri, teks kanan) jika wadahnya lebih dari 400px.","h":"container-type: inline-size pada wadah, lalu @container.","a":".wadah { container-type: inline-size; }\n.kartu { display: grid; gap: 1rem; }\n@container (min-width: 400px) {\n  .kartu { grid-template-columns: 160px 1fr; }\n}","lang":"css"},{"q":"Kapan container query lebih tepat daripada media query?","h":"Saat komponen yang sama dipakai di tempat dengan lebar berbeda (sidebar vs konten utama).","a":"/* media query: melihat lebar LAYAR\n   container query: melihat lebar WADAH komponen\n   → kartu yang sama bisa tampil sempit di sidebar\n     dan lebar di area utama tanpa class tambahan */","lang":"css"}],"deep":{"ist":[["Container query","Gaya berdasarkan ukuran kontainer, bukan viewport; komponen menyesuaikan di mana pun ia diletakkan."],["container-type: inline-size","Menjadikan elemen kontainer yang bisa diquery lebarnya."],["cqi / cqw","Unit relatif ke ukuran kontainer."],["Intrinsic design","Komponen yang responsif sendiri tanpa tahu tata letak halaman."]],"cx":[{"t":"Kartu produk yang menyesuaikan lebar slotnya","b":"Kartu yang sama tampil vertikal di grid tiga kolom, horizontal di daftar lebar, dan ringkas di sidebar, tanpa kelas tambahan.","code":".slot-kartu { container: kartu / inline-size; }\n\n.kartu { display: grid; gap: .75rem; }\n.kartu__judul { font-size: clamp(1rem, 4cqi, 1.375rem); }\n\n@container kartu (width >= 28rem) {          /* slot lebar: gambar di samping */\n  .kartu { grid-template-columns: 160px 1fr; align-items: center; }\n}\n@container kartu (width < 16rem) {           /* slot sangat sempit (sidebar): sembunyikan deskripsi */\n  .kartu__deskripsi { display: none; }\n}","lang":"css"}]}},{"lang":"html","b":["Gambar sering menjadi bagian terberat halaman. <code>srcset</code> dan <code>sizes</code> memberi browser beberapa ukuran sehingga HP tidak mengunduh gambar selebar desktop. <code>&lt;picture&gt;</code> menambahkan format modern seperti AVIF dan WebP dengan cadangan JPEG.","<code>aspect-ratio</code> menjaga proporsi kotak, misalnya 16/9 untuk video atau 1/1 untuk foto produk, bahkan sebelum gambar dimuat, sehingga tata letak tidak bergeser (CLS). <code>object-fit: cover</code> mengisi kotak tanpa membuat gambar gepeng.","Gabungkan dengan <code>loading=\"lazy\"</code> untuk gambar di bawah layar, tetapi jangan untuk gambar utama di atas layar, karena justru memperlambat LCP."],"pts":["srcset + sizes: browser memilih ukuran yang pas.","picture untuk AVIF/WebP dengan cadangan.","aspect-ratio mencegah tata letak bergeser.","Jangan lazy-load gambar utama di atas layar."],"q":[["Apa guna sizes=\"(min-width: 768px) 33vw, 100vw\"?",["Memberi tahu browser lebar gambar di layar agar memilih file yang tepat","Mengubah ukuran gambar di server","Memotong gambar"],0,"Browser memakai sizes untuk memilih kandidat srcset."],["object-fit: cover membuat gambar?",["Mengisi kotak tanpa gepeng, sebagian bisa terpotong","Selalu terlihat utuh dengan ruang kosong","Menjadi hitam putih"],0,"cover mempertahankan proporsi sambil memenuhi kotak."]],"code":"<picture>\n  <source type=\"image/avif\" srcset=\"kopi-400.avif 400w, kopi-800.avif 800w\">\n  <source type=\"image/webp\" srcset=\"kopi-400.webp 400w, kopi-800.webp 800w\">\n  <img src=\"kopi-800.jpg\" alt=\"Kopi Gayo dalam kemasan 250 gram\"\n       srcset=\"kopi-400.jpg 400w, kopi-800.jpg 800w\"\n       sizes=\"(min-width: 768px) 33vw, 100vw\"\n       width=\"800\" height=\"800\" loading=\"lazy\">\n</picture>\n\n<style>\n.foto-produk {\n  width: 100%;\n  aspect-ratio: 1 / 1;\n  object-fit: cover;\n  border-radius: 12px;\n}\n</style>","run":false,"deep":{"ist":[["aspect-ratio","Menjaga rasio kotak (16/9, 1/1) bahkan sebelum gambar dimuat; mencegah layout shift."],["object-fit: cover / contain","Mengisi kotak dengan memotong, atau memuat seluruh gambar dengan ruang kosong."],["object-position","Menentukan bagian gambar yang tetap terlihat saat dipotong."],["max-width: 100%","Mencegah gambar lebih lebar dari kontainernya."]],"cx":[{"t":"Thumbnail seragam dari foto berbagai ukuran","code":"img, video { max-width: 100%; height: auto; display: block; }\n\n.thumb {\n  aspect-ratio: 1;                 /* kotak sempurna */\n  width: 100%;\n  object-fit: cover;               /* isi penuh, potong bagian berlebih */\n  object-position: 50% 30%;        /* utamakan bagian atas-tengah (wajah, label produk) */\n  border-radius: .75rem;\n  background: var(--abu-100);      /* placeholder saat memuat */\n}\n.logo-mitra { aspect-ratio: 3 / 1; object-fit: contain; }   /* logo jangan terpotong */\n.video-embed { aspect-ratio: 16 / 9; width: 100%; }","lang":"css"}]}},{"b":["Combinator memilih berdasarkan hubungan: <code>nav a</code> (keturunan), <code>ul &gt; li</code> (anak langsung), <code>h2 + p</code> (saudara tepat setelahnya), <code>h2 ~ p</code> (semua saudara setelahnya). Selector atribut: <code>a[href^=\"https\"]</code>, <code>input[type=\"email\"]</code>.","<b>Pseudo-class</b> memilih keadaan: <code>:hover</code>, <code>:focus-visible</code>, <code>:checked</code>, <code>:nth-child(2n)</code>, <code>:not(.aktif)</code>, <code>:has(img)</code>. <b>Pseudo-element</b> menata bagian elemen: <code>::before</code>, <code>::after</code>, <code>::first-letter</code>, <code>::placeholder</code>."],"html":"<ul class=\"daftar\">\n  <li>Kopi Gayo</li><li class=\"habis\">Rendang Kaleng</li><li>Teh Melati</li><li>Keripik</li>\n</ul>\n<a href=\"https://roadmap.sh\">Tautan luar</a> · <a href=\"#bawah\">Tautan dalam</a>","css":".daftar > li { padding: 6px; font: 14px sans-serif; }\n.daftar > li:nth-child(even) { background: #F2F1EC; }\n.daftar li:not(.habis):hover { background: #FBE7A8; }\n.habis::after { content: \" (habis)\"; color: #B23A2E; font-size: 12px; }\na[href^=\"https\"]::after { content: \" ↗\"; }","task":{"q":"Buat baris pertama daftar bercetak tebal memakai <code>:first-child</code>.","test":"getComputedStyle(document.querySelector('.daftar li')).fontWeight>=600","hint":".daftar > li:first-child { font-weight: 700; }"},"pts":["spasi = keturunan, > = anak langsung, + = saudara berikutnya, ~ = semua saudara berikutnya.","Pseudo-class untuk keadaan, pseudo-element untuk bagian.",":has() memilih induk berdasarkan isinya."],"q":[["Selector untuk baris genap?",[":nth-child(even)",":even",":nth(2)"],0,"Atau :nth-child(2n)."]],"so":[{"q":"Beri warna belang pada baris tabel genap dan sorot baris saat di-hover.","h":":nth-child(even) dan :hover.","a":"tbody tr:nth-child(even) { background: #F5F2EC; }\ntbody tr:hover { background: #FBE7A8; }","lang":"css"},{"q":"Tambahkan ikon panah setelah setiap link eksternal tanpa mengubah HTML.","h":"Selector atribut a[href^=\"http\"] dan ::after.","a":"a[href^=\"http\"]::after {\n  content: \" ↗\";\n  font-size: 0.8em;\n}","lang":"css"}],"deep":{"ist":[["Combinator","Spasi (keturunan), > (anak langsung), + (saudara berikutnya), ~ (saudara setelahnya)."],["Pseudo-class","Status elemen: :hover, :focus-visible, :checked, :nth-child(), :empty, :is(), :where()."],["Pseudo-element","Bagian virtual: ::before, ::after, ::placeholder, ::marker, ::selection."],[":focus-visible","Cincin fokus hanya untuk navigasi keyboard, bukan klik mouse."]],"cx":[{"t":"Pola umum dengan combinator dan pseudo","code":".tumpuk > * + * { margin-block-start: 1rem; }               /* \"lobotomized owl\": jarak antar anak */\n.tabel tbody tr:nth-child(even) { background: var(--abu-50); }\n.daftar li:not(:last-child) { border-block-end: 1px solid var(--garis); }\n:is(h1, h2, h3):where(.artikel *) { scroll-margin-top: 5rem; }   /* :where = specificity 0 */\n\n.tombol:focus-visible { outline: 3px solid var(--fokus); outline-offset: 2px; }\n.input:placeholder-shown + .label { opacity: .6; }\n.kotak:empty::before { content: \"Belum ada data\"; color: var(--teks-lembut); }\n.wajib::after { content: \" *\"; color: var(--merah-700); }\ninput[type=\"checkbox\"]:checked + label { text-decoration: line-through; }","lang":"css"}]}},{"b":["<code>transform</code> menggeser (<code>translate</code>), memutar (<code>rotate</code>), dan mengubah skala (<code>scale</code>) tanpa mengganggu tata letak elemen lain.","<code>transition</code> menghaluskan perubahan nilai, misalnya saat hover: <code>transition: transform .2s ease</code>. <code>@keyframes</code> membuat animasi bertahap yang bisa berulang.","Animasikan <code>transform</code> dan <code>opacity</code> saja bila bisa, karena paling ringan untuk browser. Hormati <code>prefers-reduced-motion</code>."],"html":"<button class=\"tombol\">Arahkan kursor</button>\n<div class=\"loader\" aria-label=\"Memuat\"></div>","css":".tombol { padding: 10px 18px; border: 0; border-radius: 99px; background: #1C1B19; color: #fff; transition: transform .2s ease, box-shadow .2s; }\n.tombol:hover { transform: translateY(-3px) scale(1.04); box-shadow: 0 8px 18px rgb(0 0 0 / 25%); }\n.loader { width: 28px; height: 28px; margin-top: 16px; border: 3px solid #ddd; border-top-color: #2E5E8C; border-radius: 50%; animation: putar 1s linear infinite; }\n@keyframes putar { to { transform: rotate(360deg); } }\n@media (prefers-reduced-motion: reduce) { .loader { animation-duration: 3s; } }","pts":["transform tidak menggeser elemen lain.","transition untuk perubahan halus, keyframes untuk animasi bertahap.","Animasikan transform dan opacity.","Hormati prefers-reduced-motion."],"q":[["Properti yang paling ringan dianimasikan?",["transform dan opacity","width dan height","margin"],0,"Keduanya tidak memicu hitung ulang tata letak."]],"so":[{"q":"Buat kartu yang terangkat 4px dan bayangannya menebal saat di-hover, dengan transisi 200ms.","h":"transform: translateY(-4px) dan transition pada transform dan box-shadow.","a":".kartu {\n  transition: transform .2s ease, box-shadow .2s ease;\n}\n.kartu:hover {\n  transform: translateY(-4px);\n  box-shadow: 0 8px 24px rgb(0 0 0 / .12);\n}","lang":"css"},{"q":"Buat ikon memuat yang berputar terus.","h":"@keyframes dengan rotate 0 ke 360deg, animation infinite linear.","a":"@keyframes putar { to { transform: rotate(360deg); } }\n.memuat {\n  width: 24px; height: 24px;\n  border: 3px solid #ddd;\n  border-top-color: #B4532A;\n  border-radius: 50%;\n  animation: putar 0.8s linear infinite;\n}","lang":"css"}],"deep":{"ist":[["Composited properties","transform dan opacity dianimasikan GPU tanpa layout ulang; murah dan mulus."],["transition","Perubahan halus antar dua state; tentukan properti, durasi, dan easing."],["@keyframes","Animasi multi-langkah yang bisa berulang."],["View Transitions","API untuk animasi perpindahan halaman/state (startViewTransition dan @view-transition)."]],"cx":[{"t":"Animasi yang mulus dan menghormati preferensi pengguna","code":".kartu { transition: transform 200ms cubic-bezier(.2,.8,.2,1), box-shadow 200ms; }\n.kartu:hover { transform: translateY(-4px); }\n\n@keyframes kerangka { from { background-position: 200% 0; } to { background-position: -200% 0; } }\n.skeleton {\n  background: linear-gradient(90deg, var(--abu-100) 25%, var(--abu-200) 50%, var(--abu-100) 75%);\n  background-size: 200% 100%; animation: kerangka 1.4s linear infinite;\n}\n/* hindari menganimasikan width/height/top/left: memicu layout setiap frame */\n.toast { translate: 0 120%; transition: translate 250ms ease-out; }\n.toast.tampil { translate: 0 0; }\n\n@view-transition { navigation: auto; }        /* transisi halus antar halaman MPA */\n@media (prefers-reduced-motion: reduce) { .skeleton { animation: none; } }","lang":"css"}]}},{"lang":"css","b":["Selama bertahun-tahun CSS tidak bisa memilih elemen <b>berdasarkan isinya</b>. <code>:has()</code> mengubah itu: <code>.kartu:has(img)</code> memilih kartu yang berisi gambar, dan <code>form:has(:invalid)</code> memilih form yang masih punya isian salah.","Ini membuat banyak JavaScript kecil tidak diperlukan lagi, misalnya menandai label saat checkbox di dalamnya dicentang. Hati-hati memakai <code>:has()</code> pada elemen yang sangat umum seperti <code>body</code>, karena browser harus memeriksa ulang saat isinya berubah.","CSS kini juga mendukung <b>nesting</b> tanpa Sass: aturan untuk anak elemen ditulis di dalam blok induknya, dan <code>&amp;</code> merujuk induk itu sendiri."],"pts":[":has() memilih elemen berdasarkan isinya.","Mengganti JavaScript kecil untuk status visual.","Hindari :has() pada elemen sangat umum.","Nesting bawaan dengan & tanpa Sass."],"q":[["Selector untuk kartu yang berisi gambar?",[".kartu:has(img)",".kartu img","img .kartu"],0,".kartu img memilih gambarnya, bukan kartunya."],["Dalam nesting CSS, & merujuk ke?",["Selector induk","Elemen berikutnya","Elemen html"],0,"& menggantikan selector blok induknya."]],"code":"/* kartu dengan gambar memakai tata letak dua kolom */\n.kartu:has(img) { display: grid; grid-template-columns: 120px 1fr; gap: 12px; }\n\n/* tombol kirim redup selama ada isian yang salah */\nform:has(:invalid) button[type=\"submit\"] { opacity: .5; }\n\n/* label ikut tersorot saat pilihannya dicentang */\n.pilihan:has(input:checked) { border-color: var(--brand); background: var(--brand-soft); }\n\n/* nesting bawaan CSS */\n.menu {\n  display: flex;\n  & a { padding: 8px 12px; }\n  & a:hover { text-decoration: underline; }\n}","run":false,"deep":{"ist":[[":has()","Memilih elemen berdasarkan isi atau saudaranya; \"parent selector\" yang lama ditunggu."],["Native CSS nesting","Menulis aturan bersarang langsung di CSS (& untuk induk), tanpa Sass."],["Form state styling","form:has(:user-invalid) untuk menandai form yang masih punya error."],["Progressive enhancement","Fitur baru dipakai sebagai peningkatan; halaman tetap berfungsi di browser lama."]],"cx":[{"t":":has() dan nesting tanpa JavaScript","code":".kartu {\n  padding: 1rem;\n  &:has(img) { padding-block-start: 0; }                 /* kartu bergambar */\n  &:has(.lencana--habis) { opacity: .6; }                 /* produk habis tampak redup */\n  & .judul { font-weight: 600; }\n  &:hover .judul { text-decoration: underline; }\n  @media (width >= 40rem) { padding: 1.5rem; }\n}\n.field:has(input:user-invalid) label { color: var(--merah-700); }\nform:has(:user-invalid) button[type=\"submit\"] { opacity: .5; }\nbody:has(dialog[open]) { overflow: hidden; }              /* kunci gulir saat modal terbuka */\n.galeri:has(> :nth-child(5)) { grid-template-columns: repeat(3, 1fr); }  /* 5+ foto: 3 kolom */","lang":"css"}]}},{"b":["<b>Custom property</b> (variabel CSS) ditulis <code>--nama: nilai</code> dan dipakai dengan <code>var(--nama)</code>. Berbeda dengan variabel Sass, variabel CSS hidup di browser: bisa diubah oleh media query, oleh class, atau oleh JavaScript.","Ini dasar dari tema terang-gelap dan design token. Tulis semua warna di <code>:root</code>, lalu ganti nilainya untuk tema gelap."],"html":"<div class=\"kartu\"><h3>Mode tema</h3><p>Klik tombol untuk ganti tema.</p>\n<button onclick=\"document.documentElement.classList.toggle('gelap')\">Ganti tema</button></div>","css":":root { --bg: #FAFAF7; --teks: #1C1B19; --aksen: #B4532A; --radius: 12px; }\n:root.gelap { --bg: #181816; --teks: #ECEAE4; --aksen: #E39A73; }\nbody { background: var(--bg); color: var(--teks); font-family: sans-serif; transition: background .3s; }\n.kartu { border: 2px solid var(--aksen); border-radius: var(--radius); padding: 12px 16px; }\nbutton { background: var(--aksen); color: var(--bg); border: 0; padding: 6px 14px; border-radius: 99px; }","task":{"q":"Ganti <code>--radius</code> menjadi <code>0px</code> agar kartu bersudut tajam.","test":"getComputedStyle(document.querySelector('.kartu')).borderTopLeftRadius==='0px'","hint":":root { --radius: 0px; }"},"pts":["--nama untuk mendefinisikan, var(--nama) untuk memakai.","Variabel CSS bisa diubah saat halaman berjalan.","Dasar tema gelap dan design token."],"q":[["Cara memakai variabel --aksen?",["var(--aksen)","$aksen","@aksen"],0,"Fungsi var() membaca custom property."]],"so":[{"q":"Definisikan warna merek dan jarak sebagai variabel, lalu buat tema gelap dengan atribut data-theme.","h":"Variabel di :root, ditimpa di [data-theme=\"dark\"].","a":":root {\n  --bg: #FBF8F3;\n  --fg: #1A1A1A;\n  --merek: #B4532A;\n  --jarak: 1rem;\n}\n[data-theme=\"dark\"] {\n  --bg: #14161A;\n  --fg: #ECE7DF;\n  --merek: #E39A73;\n}\nbody { background: var(--bg); color: var(--fg); }\n.btn { background: var(--merek); padding: var(--jarak); }","lang":"css"},{"q":"Beri nilai cadangan jika variabel belum didefinisikan.","h":"var(--nama, cadangan).","a":".kartu { border-radius: var(--radius, 12px); }","lang":"css"}],"pro":[{"t":"Warna disimpan di satu tempat","tag":"Best practice","why":"Kode warna yang diulang di banyak tempat sulit diganti dan mudah berbeda sedikit. Custom property menyimpannya sekali, dan tema gelap cukup mengganti nilainya.","lang":"css","a":".tombol { background: #255DA2; }\n.tautan { color: #255DA2; }\n.badge  { border-color: #255da2; }","b":":root { --warna-utama: #255DA2; }\n@media (prefers-color-scheme: dark) { :root { --warna-utama: #79ACEE; } }\n.tombol { background: var(--warna-utama); }\n.tautan { color: var(--warna-utama); }\n.badge  { border-color: var(--warna-utama); }"}],"deep":{"ist":[["Custom property","--nama: nilai; dibaca dengan var(--nama, cadangan); bisa diubah saat runtime."],["Design token tiers","Primitive (--hijau-700) -> semantic (--warna-aksi) -> component (--tombol-latar)."],["Theming","Mengganti nilai token di [data-theme=\"gelap\"] atau media query, tanpa menyentuh komponen."],["@property","Mendaftarkan tipe custom property agar bisa dianimasikan."]],"cx":[{"t":"Token tiga lapis dan tema gelap","code":":root {\n  /* primitive */\n  --hijau-600: oklch(55% 0.15 150); --hijau-700: oklch(48% 0.14 150);\n  --abu-50: oklch(98% 0 0); --abu-900: oklch(20% 0.01 150);\n  /* semantic */\n  --warna-latar: var(--abu-50); --warna-teks: var(--abu-900); --warna-aksi: var(--hijau-700);\n  /* component */\n  --tombol-latar: var(--warna-aksi); --tombol-teks: white; --radius: .75rem;\n}\n[data-theme=\"gelap\"] { --warna-latar: var(--abu-900); --warna-teks: var(--abu-50); --warna-aksi: var(--hijau-600); }\n@media (prefers-color-scheme: dark) { :root:not([data-theme=\"terang\"]) { --warna-latar: var(--abu-900); --warna-teks: var(--abu-50); } }\n\nbody { background: var(--warna-latar); color: var(--warna-teks); }\n.tombol { background: var(--tombol-latar); color: var(--tombol-teks); border-radius: var(--radius); }\n\n@property --progres { syntax: \"<percentage>\"; inherits: false; initial-value: 0%; }\n.bar { background: linear-gradient(90deg, var(--warna-aksi) var(--progres), transparent 0); transition: --progres .4s; }","lang":"css"}]}},{"lang":"scss","run":false,"b":["Di proyek besar, nama class mudah bentrok. <b>BEM</b> (Block__Element--Modifier) memberi aturan penamaan: <code>.kartu</code>, <code>.kartu__judul</code>, <code>.kartu--promo</code>. Specificity tetap rendah dan maksud setiap class jelas.","<b>Sass</b> menambah fitur seperti nesting, mixin, dan fungsi, lalu dikompilasi menjadi CSS biasa. <b>PostCSS</b> memproses CSS dengan plugin, misalnya menambahkan prefix browser otomatis. <b>CSS Modules</b> dan <b>CSS-in-JS</b> membuat nama class unik per komponen secara otomatis.","Untuk performa: kirim CSS sekecil mungkin, hapus aturan yang tidak dipakai, dan muat CSS kritis lebih awal karena CSS menghambat tampilnya halaman."],"code":"// Sass dengan penamaan BEM\n$aksen: #B4532A;\n\n@mixin kartu-dasar {\n  border-radius: 12px;\n  padding: 16px;\n}\n\n.kartu {\n  @include kartu-dasar;\n  border: 1px solid #ddd;\n\n  &__judul { font-weight: 600; }        // .kartu__judul\n  &--promo { border-color: $aksen; }    // .kartu--promo\n}","pts":["BEM: blok__elemen--modifier.","Sass dikompilasi menjadi CSS biasa.","CSS Modules membuat nama class unik otomatis.","CSS menghambat tampil halaman: jaga tetap ramping."],"q":[["Dalam BEM, .tombol--besar adalah?",["Modifier dari blok tombol","Elemen anak tombol","Blok baru"],0,"Dua tanda hubung untuk modifier."]],"so":[{"q":"Beri nama class BEM untuk kartu produk berisi judul, harga, dan varian kartu \"unggulan\".","h":"blok__elemen--modifier.","a":".kartu { }\n.kartu__judul { }\n.kartu__harga { }\n.kartu--unggulan { border-color: gold; }","lang":"css"},{"q":"Tulis versi Sass dengan nesting dan variabel untuk tombol beserta keadaan hover.","h":"Variabel $nama, nesting dengan &.","a":"$merek: #B4532A;\n\n.btn {\n  background: $merek;\n  color: white;\n  &:hover { background: darken($merek, 8%); }\n  &--besar { padding: 1rem 2rem; }\n}","lang":"scss"}],"deep":{"ist":[["BEM","Block__Element--Modifier: konvensi nama kelas yang menghindari bentrok (kartu__judul--besar)."],["Sass","Preprocessor dengan variabel, mixin, dan partial; sebagian fiturnya kini ada di CSS asli."],["CSS Modules","Nama kelas diberi hash otomatis per komponen sehingga tidak bentrok antar berkas."],["Unused CSS","CSS yang tidak terpakai memperlambat render; ukur di DevTools Coverage dan hapus."]],"cx":[{"t":"Satu komponen dalam tiga gaya penulisan","code":"/* BEM (CSS biasa) */\n.kartu { … }  .kartu__judul { … }  .kartu--unggulan { … }\n\n/* Sass: mixin dan partial */\n@use \"token\" as t;\n@mixin fokus { outline: 3px solid t.$fokus; outline-offset: 2px; }\n.tombol { &:focus-visible { @include fokus; } }\n\n/* CSS Modules: Kartu.module.css */\n.judul { font-weight: 600; }\n/* Kartu.jsx */\n/* import s from \"./Kartu.module.css\";  <h3 className={s.judul}>  ->  class=\"Kartu_judul__x7a2q\" */","lang":"css"},{"t":"Mengukur CSS yang tidak terpakai (simulasi panel Coverage)","code":"const aturan = [\".kartu\", \".kartu__judul\", \".tombol\", \".tombol--besar\", \".modal\", \".carousel\", \".carousel__slide\", \".lencana\"];\nconst dipakaiDiHalaman = new Set([\".kartu\", \".kartu__judul\", \".tombol\", \".lencana\"]);\nconst tidak = aturan.filter((a) => !dipakaiDiHalaman.has(a));\nconsole.log(`${tidak.length}/${aturan.length} aturan tidak terpakai (${Math.round(100 * tidak.length / aturan.length)}%):`, tidak.join(\" \"));\nconsole.log(\"tindakan: pecah CSS per halaman/komponen, atau muat .modal dan .carousel saat dibutuhkan\");","lang":"js","out":"4/8 aturan tidak terpakai (50%): .tombol--besar .modal .carousel .carousel__slide\ntindakan: pecah CSS per halaman/komponen, atau muat .modal dan .carousel saat dibutuhkan"}]}},{"stack":"HTML + CSS","brief":"Tata ulang halaman produk Toko Nusantara menjadi landing page yang rapi di ponsel dan desktop, dengan tema terang-gelap memakai variabel CSS.","feats":["Variabel CSS untuk warna, radius, dan jarak di :root","Tema gelap otomatis lewat prefers-color-scheme","Header dengan flexbox: logo kiri, menu kanan, pindah baris di ponsel","Galeri produk dengan grid auto-fill minmax","Kartu produk dengan penamaan BEM dan efek hover memakai transform","Tipografi: clamp untuk judul, panjang baris maksimal 65ch","Fokus keyboard terlihat (:focus-visible)","Tidak ada scroll horizontal di lebar 360px"],"steps":["Tulis HTML semantik terlebih dahulu.","Definisikan variabel di :root, lalu versi gelapnya.","Bangun header (flex) dan galeri (grid).","Uji di 360px, 768px, dan 1280px."],"files":[["gaya.css","css",":root{--bg:#FAFAF7;--teks:#1C1B19;--redup:#6E6B64;--aksen:#B4532A;--kartu:#fff;--garis:#E7E5DF;--r:14px}\n@media (prefers-color-scheme:dark){:root{--bg:#111110;--teks:#ECEAE4;--redup:#9C988F;--aksen:#E39A73;--kartu:#181816;--garis:#2A2925}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--teks);font:16px/1.6 system-ui,sans-serif}\n.header{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;padding:16px max(16px,4vw);border-bottom:1px solid var(--garis)}\n.header__menu{display:flex;gap:16px}\n.header__menu a{color:var(--teks);text-decoration:none}\n.hero{padding:48px max(16px,4vw)}\n.hero__judul{font:400 clamp(2rem,6vw,3.5rem)/1.05 Georgia,serif;max-width:18ch;margin:0}\n.hero__teks{color:var(--redup);max-width:65ch}\n.galeri{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px;padding:0 max(16px,4vw) 48px}\n.kartu{background:var(--kartu);border:1px solid var(--garis);border-radius:var(--r);padding:16px;transition:transform .2s,box-shadow .2s}\n.kartu:hover{transform:translateY(-4px);box-shadow:0 12px 28px rgb(0 0 0/.12)}\n.kartu__harga{color:var(--aksen);font-weight:600}\n.kartu--promo{border-color:var(--aksen)}\na:focus-visible,button:focus-visible{outline:3px solid var(--aksen);outline-offset:2px}"],["index.html","html","<header class=\"header\">\n  <strong>Toko Nusantara</strong>\n  <nav class=\"header__menu\"><a href=\"#produk\">Produk</a><a href=\"#kontak\">Kontak</a></nav>\n</header>\n<main>\n  <section class=\"hero\">\n    <h1 class=\"hero__judul\">Rasa Nusantara, diantar ke rumahmu</h1>\n    <p class=\"hero__teks\">Kopi, teh, dan camilan dari petani lokal.</p>\n  </section>\n  <section class=\"galeri\" id=\"produk\">\n    <article class=\"kartu kartu--promo\"><h2>Kopi Gayo</h2><p class=\"kartu__harga\">Rp85.000</p></article>\n    <article class=\"kartu\"><h2>Teh Melati</h2><p class=\"kartu__harga\">Rp25.000</p></article>\n    <article class=\"kartu\"><h2>Madu Hutan</h2><p class=\"kartu__harga\">Rp120.000</p></article>\n  </section>\n</main>"]],"preview":true,"deep":{"ist":[["Above the fold","Bagian yang terlihat tanpa menggulir; berisi proposisi nilai dan satu ajakan utama."],["Call to action (CTA)","Tombol utama (\"Pesan sekarang\") yang kontras dan konsisten."],["Core Web Vitals","LCP < 2,5 s, INP < 200 ms, CLS < 0,1 sebagai target kualitas halaman."],["Visual regression test","Membandingkan tangkapan layar sebelum dan sesudah perubahan CSS untuk menangkap kerusakan tampilan."]],"cx":[{"t":"Kerangka CSS landing page yang cepat","code":"@layer reset, token, layout, komponen;\n@layer layout {\n  .wadah { max-width: 72rem; margin-inline: auto; padding-inline: clamp(1rem, 4vw, 2rem); }\n  .hero { display: grid; gap: 2rem; align-items: center; min-height: min(80dvh, 44rem); }\n  @media (width >= 56rem) { .hero { grid-template-columns: 1.1fr 1fr; } }\n  .fitur { display: grid; gap: 1.5rem; grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr)); }\n}\n@layer komponen {\n  .cta { display: inline-flex; align-items: center; gap: .5rem; min-block-size: 48px; padding-inline: 1.5rem;\n         background: var(--warna-aksi); color: white; border-radius: var(--radius); font-weight: 600; }\n  .hero img { aspect-ratio: 4 / 3; width: 100%; object-fit: cover; border-radius: 1.5rem; }\n  .testimoni { border-inline-start: 4px solid var(--warna-aksi); padding-inline-start: 1rem; }\n}\n/* Checklist sebelum rilis: 360px tanpa gulir samping, kontras AA, fokus terlihat, Lighthouse >= 90 */","lang":"css"}]}},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]);
